import java.io.*;
import java.util.*;





public class MinCostMaxFlow {
    public static void main(String[] args) {
        InputReader in = new InputReader();
        OutputWriter out = new OutputWriter(System.out);
		int letters = 'z' - 'a' + 1;
        int n = in.nextInt();
        String s = in.next();
        char[] string = s.toCharArray();
        int[] letCount = new int[letters];
        for(int i = 0; i < n; ++i) {
            letCount[string[i] - 'a']++;
        }
        int[] b = new int[n];
        for(int i = 0; i < n; ++i) {
            b[i] = in.nextInt();
        }

        int source = 0;
        int charOffSet = 1;
        int pairOffSet = charOffSet + letters;
        int sinkOffSet = pairOffSet + n / 2;
        int sink = sinkOffSet;
        int vNum = sinkOffSet + 1;

        Graph g = new Graph(vNum, source, sink);
        //Source -> Letters -> Pairs
        for(int i = 0; i < letters; ++i) {
            g.addEdge(source, charOffSet + i, letCount[i], 0);
            for(int j = 0; j < n/2; ++j) {
                char c1 = string[j];
                char c2 = string[n - j - 1];
                if(c1 == 'a' + i) {
                    if(c1 == c2) {
                        g.addEdge(charOffSet + i, pairOffSet + j,
                            1, -Integer.max(b[j], b[n - j - 1]));
                    } else {
                        g.addEdge(charOffSet + i, pairOffSet + j, 1, -b[j]);
                    }
                } else {
                    if(c2 == 'a' + i) {
                        g.addEdge(charOffSet + i, pairOffSet + j, 1, -b[n - j - 1]);
                    } else {
                        g.addEdge(charOffSet + i, pairOffSet + j, 1, 0);
                    }
                }
            }
        }
        //Pairs -> Sink
        for(int i = 0; i < n/2; ++i) {
            g.addEdge(pairOffSet + i, sink, 2, 0);
        }

        int[] ans = g.getMinCostMaxFlow();
//		System.out.println("flow: " + ans[0]);
//		System.out.println("cost: " + -ans[1]);
        System.out.println(-ans[1]);
    }




    public static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void printf(String format, Object... objects) {
            writer.printf(format, objects);
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }

    }

    static class InputReader
    {
        BufferedReader br;
        StringTokenizer st;

        public InputReader()
        {
            br = new BufferedReader(new
                     InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

class Graph {
    private int vNum;
    private int src;
    private int sink;

    private int[][] res;
    private int[][] cost;
    private List<Edge> costGraph;
    private int[] p;
    private int[] d;

    private static class Edge {
      final int from;
      final int to;
      final int cost;

      Edge(int from, int to, int cost) {
          this.from = from;
          this.to = to;
          this.cost = cost;
      }
  }

    public int getVertexNumber() {
        return vNum;
    }

    public Graph(int vNum, int src, int sink) {
        this.vNum = vNum;
        this.src = src;
        this.sink = sink;
        res = new int[vNum][vNum];
        cost = new int[vNum][vNum];
        costGraph = new ArrayList<>();
        d = new int[vNum];
        p = new int[vNum];
    }

    public void addEdge(int from, int to, int capacity, int cost) {
        res[from][to] += capacity;
        this.cost[from][to] = cost;
        this.cost[to][from] = -cost;

    }

    private boolean findCheapestPath() {
    	costGraph.clear();
    	for(int i = 0; i < vNum; ++i) {
    		for(int j = 0; j < vNum; ++j) {
    			if(res[i][j] > 0) {
    				costGraph.add(new Edge(i, j, cost[i][j]));
    			}
    		}
    	}

    	Arrays.fill(d, Integer.MAX_VALUE);
    	Arrays.fill(p, -1);

    	d[src] = 0;

    	boolean changed = false;
    	for(int i = 0; i < vNum - 1; ++i) {
    		for(Edge e: costGraph) {
    			// Be careful here
    			// Overfloating can be
    			if(d[e.from] != Integer.MAX_VALUE && d[e.from] + e.cost < d[e.to]) {
    				d[e.to] = d[e.from] + e.cost;
    				p[e.to] = e.from;
    				changed = true;
    			}
    		}
    		if(!changed) {
    			break;
    		}
    	}

    	return p[sink] != -1;
    }

    private int[] augmentPath(int from, int to, int flow) {
    	int pathCost = 0;
    	for(int cur = to; cur != from; cur = p[cur]) {
    		flow = Integer.min(flow, res[p[cur]][cur]);
    	}
    	for(; to != from; to = p[to]) {
    		res[p[to]][to] -= flow;
    		res[to][p[to]] += flow;
    		pathCost += cost[p[to]][to] * flow;
    	}
    	return new int[] {flow, pathCost};
    }

    public int[] getMinCostMaxFlow() {
    	int flow = 0;
    	int totalCost = 0;
    	while(findCheapestPath()) {
    		int[] result = augmentPath(src, sink, Integer.MAX_VALUE);
    		flow += result[0];
    		totalCost += result[1];
    	}    	
    	return new int[] {flow, totalCost};
    }
}

